"""Shared helpers for the labs: make the data if it's missing, open DuckDB, and print query results."""

import os
import subprocess
import sys

import duckdb


def connect():
    if not os.path.isdir("bi_data"):
        subprocess.run([sys.executable, "make_bi_data.py"], check=True)
    con = duckdb.connect()
    con.sql("CREATE VIEW sales AS SELECT *, quantity * unit_price * (1 - discount) AS revenue "
            "FROM 'bi_data/orders.csv'")
    return con


def show(con, title, sql):
    """Run a query and print it as a plain table, numbers rounded, the same in every DuckDB version."""
    rel = con.sql(sql)
    rows = rel.fetchall()
    def fmt(v):
        if isinstance(v, float):
            if abs(v) < 1:
                return f"{v:.3f}"
            return f"{v:,.2f}" if abs(v) < 1000 else f"{v:,.0f}"
        if isinstance(v, int):
            return f"{v:,}" if abs(v) >= 10000 else str(v)
        return str(v)
    cells = [[fmt(v) for v in row] for row in rows]
    widths = [max(len(c), *(len(r[i]) for r in cells)) for i, c in enumerate(rel.columns)]
    print(f"\n{title}")
    print("  ".join(c.ljust(w) for c, w in zip(rel.columns, widths)))
    for r in cells:
        print("  ".join(v.rjust(w) if v[:1].isdigit() or v[:1] == "-" else v.ljust(w) for v, w in zip(r, widths)))
    return rows

